import csv,io,time

def load_snapshot():
    time.sleep(0.150)
    return [{'name':'Cup','quantity':2},{'name':'Plate','quantity':0}]

def render_csv(rows):
    out=io.StringIO(newline='')
    writer=csv.writer(out,lineterminator='\n')
    writer.writerow(['name','quantity'])
    writer.writerows((row['name'],row['quantity']) for row in rows)
    return out.getvalue()

def export_inventory():
    return render_csv(load_snapshot())
